// App version shown in the sidebar. The real source of truth is CACHE_VERSION in
// public/sw.js (the only thing bumped each deploy) — the badge asks the active
// service worker for it at runtime. This value is just the fallback shown when no
// service worker is available (e.g. very first visit before it installs).
var APP_VERSION = 'v122';
var _resolvedAppVersion = null;

// Ask the active service worker for its CACHE_VERSION (without the 'nova-' prefix).
function getServiceWorkerVersion() {
  return new Promise(function (resolve) {
    if (_resolvedAppVersion) { resolve(_resolvedAppVersion); return; }
    if (!('serviceWorker' in navigator)) { resolve(null); return; }
    navigator.serviceWorker.ready.then(function (reg) {
      var sw = reg.active;
      if (!sw) { resolve(null); return; }
      var ch = new MessageChannel();
      var done = false;
      ch.port1.onmessage = function (e) {
        done = true;
        if (e.data && e.data.type === 'VERSION' && e.data.version) {
          _resolvedAppVersion = e.data.version;
          resolve(e.data.version);
        } else { resolve(null); }
      };
      try { sw.postMessage({ type: 'GET_VERSION' }, [ch.port2]); }
      catch (err) { resolve(null); return; }
      setTimeout(function () { if (!done) resolve(null); }, 1500);
    }).catch(function () { resolve(null); });
  });
}

// Update the sidebar version badge. Primary source is /api/version (read from
// sw.js on the server) — the service worker never caches /api, so this is always
// the live deployed version with no lag. Falls back to asking the active service
// worker, then to the hard-coded APP_VERSION.
function refreshAppVersionBadge() {
  var el = document.getElementById('app-version');
  if (!el) return;
  if (_resolvedAppVersion) { el.textContent = _resolvedAppVersion; return; }
  fetch('/api/version', { cache: 'no-store' }).then(function (r) {
    return r.ok ? r.json() : null;
  }).then(function (d) {
    if (d && d.version) { _resolvedAppVersion = d.version; el.textContent = d.version; }
    else { getServiceWorkerVersion().then(function (v) { if (v) el.textContent = v; }); }
  }).catch(function () {
    getServiceWorkerVersion().then(function (v) { if (v) el.textContent = v; });
  });
}

const state = {
  token: localStorage.getItem('po_token'),
  user: normalizeUserRole(JSON.parse(localStorage.getItem('po_user') || 'null')),
  currentView: null,
  currentParam: null,
  sidebarSection: null,
  sidebarSub: null,             // nested sub-group open state: null=derive from view, ''=user-collapsed, id=open
  sidebarOpen: false,
  pendingUserId: null,
  pendingRemember: false,
  pendingVia: null,
  permsRev: null,               // last X-Perms-Rev seen; a change means our perms are stale
  _permsRerenderPending: false, // perms changed while on a form; re-render on next navigate
  realUser: null,
  viewAs: null,
  permissions: null,
  _permsLoaded: false,
};

// ── Global top loading bar (driven by every api() call) ──────────────────────
var _npCount = 0, _npEl = null, _npTimer = null;
function _npBar() { if (!_npEl) { _npEl = document.createElement('div'); _npEl.id = 'nova-progress'; document.body.appendChild(_npEl); } return _npEl; }
function novaProgressStart() {
  _npCount++;
  if (_npCount === 1) {
    var b = _npBar(); clearTimeout(_npTimer);
    b.style.transition = 'none'; b.style.opacity = '1'; b.style.width = '0%';
    void b.offsetWidth;
    b.style.transition = 'width 10s cubic-bezier(.1,.7,.6,1)'; b.style.width = '85%';
  }
}
function novaProgressDone() {
  _npCount = Math.max(0, _npCount - 1);
  if (_npCount === 0) {
    var b = _npBar();
    b.style.transition = 'width .25s ease, opacity .35s ease .15s';
    b.style.width = '100%'; b.style.opacity = '0';
    clearTimeout(_npTimer);
    _npTimer = setTimeout(function () { b.style.transition = 'none'; b.style.width = '0%'; }, 650);
  }
}
function novaBtnBusy(btn, label) {
  if (!btn || btn.dataset.busy) return;
  btn.dataset.busy = '1'; btn.dataset.orig = btn.innerHTML; btn.disabled = true;
  btn.innerHTML = '<span style="display:inline-block;width:14px;height:14px;border:2px solid rgba(255,255,255,.4);border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite;vertical-align:middle"></span> ' + (label || 'Saving\u2026');
}
function novaBtnReset(btn) {
  if (!btn) return;
  if (btn.dataset.busy) { btn.innerHTML = btn.dataset.orig; delete btn.dataset.busy; delete btn.dataset.orig; }
  btn.disabled = false;
}
function novaEvtBtn() { var e = window.event; var t = e && e.target; return (t && t.closest) ? t.closest('.btn') : null; }
function _novaDialog(o){
  return new Promise(function(resolve){
    var isPrompt = o.type === 'prompt', isAlert = o.type === 'alert', isSelect = o.type === 'select';
    var ov = document.createElement('div');
    ov.className = 'nova-dialog-overlay';
    var defv = (o.def != null ? String(o.def) : '').replace(/"/g, '&quot;');
    var msg = o.message ? '<div class="nova-dlg-msg">' + escHtml(o.message).replace(/\n/g, '<br>') + '</div>' : '';
    var inp = '';
    if (isPrompt) {
      inp = '<input id="nova-dlg-input" type="text" value="' + defv + '" class="nova-dlg-input">';
    } else if (isSelect) {
      var optsHtml = (o.options || []).map(function(op){
        var v = (op.value != null ? String(op.value) : '').replace(/"/g, '&quot;');
        var sel = (o.def != null && String(o.def) === String(op.value)) ? ' selected' : '';
        return '<option value="' + v + '"' + sel + '>' + escHtml(op.label != null ? op.label : op.value) + '</option>';
      }).join('');
      inp = '<select id="nova-dlg-select" class="nova-dlg-input">' +
        (o.placeholder ? '<option value="">' + escHtml(o.placeholder) + '</option>' : '') + optsHtml + '</select>';
    }
    var cancel = isAlert ? '' : '<button class="btn btn-secondary" id="nova-dlg-cancel">' + escHtml(o.cancelText || 'Never mind') + '</button>';
    ov.innerHTML = '<div class="nova-dlg" role="dialog" aria-modal="true">' +
      '<div class="nova-dlg-title">' + escHtml(o.title || '') + '</div>' + msg + inp +
      '<div class="nova-dlg-actions">' + cancel +
      '<button class="btn btn-primary" id="nova-dlg-ok">' + escHtml(o.okText || 'OK') + '</button>' +
      '</div></div>';
    document.body.appendChild(ov);
    var input = ov.querySelector('#nova-dlg-input');
    var selectEl = ov.querySelector('#nova-dlg-select');
    var okBtn = ov.querySelector('#nova-dlg-ok');
    var cancelBtn = ov.querySelector('#nova-dlg-cancel');
    if (input) { input.focus(); input.select(); } else if (selectEl) { selectEl.focus(); } else if (okBtn) { okBtn.focus(); }
    function close(val){ ov.classList.add('closing'); document.removeEventListener('keydown', onKey); setTimeout(function(){ if (ov.parentNode) ov.parentNode.removeChild(ov); }, 140); resolve(val); }
    function ok(){ close(isPrompt ? (input ? input.value : '') : (isSelect ? (selectEl ? selectEl.value : '') : true)); }
    function cancelFn(){ close((isPrompt || isSelect) ? null : false); }
    okBtn.addEventListener('click', ok);
    if (cancelBtn) cancelBtn.addEventListener('click', cancelFn);
    ov.addEventListener('mousedown', function(e){ if (e.target === ov) cancelFn(); });
    function onKey(e){ if (e.key === 'Enter') { e.preventDefault(); ok(); } else if (e.key === 'Escape') { e.preventDefault(); cancelFn(); } }
    document.addEventListener('keydown', onKey);
  });
}
function novaConfirm(message, o){ o = o || {}; return _novaDialog({ type:'confirm', message:message, title:o.title||'Quick check', okText:o.okText||'Yep, go ahead', cancelText:o.cancelText||'Never mind' }); }
function novaPrompt(message, def, o){ o = o || {}; return _novaDialog({ type:'prompt', message:message, def:def, title:o.title||'Quick one', okText:o.okText||'Save it', cancelText:o.cancelText||'Never mind' }); }
function novaAlert(message, o){ o = o || {}; return _novaDialog({ type:'alert', message:message, title:o.title||'Heads up', okText:o.okText||'Got it' }); }
function novaSelect(message, options, o){ o = o || {}; return _novaDialog({ type:'select', message:message, options:options, placeholder:o.placeholder, def:o.def, title:o.title||'Choose one', okText:o.okText||'Save it', cancelText:o.cancelText||'Never mind' }); }
// ---- App-level GET cache (stale-while-revalidate) ---------------------------
// Navigation used to re-fetch every list from Railway on each click, so revisits
// felt slow. We now serve the last response instantly from memory and quietly
// revalidate in the background. Any write (POST/PUT/PATCH/DELETE) clears the
// cache, so you never see stale data after a change.
var _apiCache = {};        // key -> { data, ts }
var _apiInflight = {};     // key -> Promise (dedupe concurrent identical GETs)
var _apiCacheGen = 0;      // bumped on every write; guards late background writes
var API_CACHE_TTL = 60000; // serve a cached copy instantly for up to 60s
var API_CACHE_SWR = 6000;  // if the cached copy is older than this, refresh in the background
function _apiNoCache(path) {
  // Endpoints that must always be live (session/auth, AI, exports, time clock, notifications).
  // A health screen must never answer from cache: a stale 'all fine' is the
  // exact failure this page exists to catch.
  return /^\/job-health/.test(path) ||
         /^\/auth(\/|$)/.test(path) || /^\/ai(\/|$)/.test(path) || /export/.test(path) ||
         /^\/goto(\/|$)/.test(path) || /^\/judi(\/|$)/.test(path) || /\/recordings(\/|$|\?)/.test(path) ||
         /setup-needed/.test(path) || /verify/.test(path) || /usage/.test(path) ||
         /token/.test(path) || /^\/timeclock/.test(path) || /notif/.test(path) ||
         /\/id-image/.test(path) || /\/dispute-packet/.test(path) || /^\/locations/.test(path) ||
         /^\/schedule\/shifts\/\d+/.test(path); // one shift + its history: always live, never cached
}
function _apiCacheKey(path) { return (state.viewAsId ? 'v' + state.viewAsId + ' ' : '') + path; }
function _apiClone(d) { try { return JSON.parse(JSON.stringify(d)); } catch (e) { return d; } }
// Clear cached reads. No arg = clear everything (used after any write); a string
// arg clears only keys containing that substring.
function apiBustCache(pattern) {
  _apiCacheGen++;
  if (!pattern) { _apiCache = {}; return; }
  Object.keys(_apiCache).forEach(function (k) { if (k.indexOf(pattern) !== -1) delete _apiCache[k]; });
}

// ---------------------------------------------------------------------------
// Live permission refresh
//
// The server stamps every authenticated response with X-Perms-Rev, a fingerprint of
// this user's role + extra_perms + active flag + the global role_permissions matrix.
// We hold the last one we saw. When it changes, our cached permissions are stale —
// an admin has changed something — so we refetch them and re-render.
//
// Without this, state.user (and therefore can(), and therefore which screens the
// sidebar routes to) is frozen at whatever it was when the user LOGGED IN, because
// the /auth/me refresh in render() is guarded by state._permsLoaded and runs once
// per page load. On a PWA left open for weeks, that is effectively forever.
// ---------------------------------------------------------------------------
var _permsRefreshing = false;

// Re-rendering blows away the DOM. That is fine on a list, and destructive on a form
// someone is halfway through filling in. On a form view we still update the in-memory
// permissions (so can() is immediately correct), but we defer the visual re-render
// until the user navigates away of their own accord.
function _permsRenderIsRisky() {
  var v = state.currentView || '';
  if (/^(new|edit)/.test(v)) return true;
  if (v.indexOf('-editor') !== -1 || v.indexOf('-form') !== -1) return true;
  var ae = document.activeElement;
  if (ae && /^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName || '')) return true;
  return false;
}

async function refreshPermsAndRerender() {
  if (_permsRefreshing) return;
  _permsRefreshing = true;
  try {
    // Use _apiFetch, not api() — a cached GET would defeat the whole point.
    try {
      var ps = await _apiFetch('GET', '/settings', null, true);
      var rp = null;
      try { rp = JSON.parse(ps.role_permissions || 'null'); } catch (e) {}
      state.permissions = rp;
    } catch (e) {}
    var me = await _apiFetch('GET', '/auth/me', null, true);
    if (me && state.user) {
      if (me.role) state.user.role = me.role;
      state.user.extra_perms = me.extra_perms || [];
      state.user = normalizeUserRole(state.user);
      try { localStorage.setItem('po_user', JSON.stringify(state.user)); } catch (e) {}
    }
    apiBustCache();
    if (_permsRenderIsRisky()) {
      // Apply on the next navigation instead of yanking the form out from under them.
      state._permsRerenderPending = true;
    } else {
      showToast('Your access was updated.', 'info');
      render();
    }
  } catch (e) {
    // Never let a failed refresh break the request the user actually made.
  } finally {
    _permsRefreshing = false;
  }
}

// ---------------------------------------------------------------------------
// Force reload (breaking deploys)
//
// Clears the service worker + every cache and reloads. Deliberately does NOT touch
// po_token / po_user — this flushes stale CODE, it is not a logout.
// ---------------------------------------------------------------------------
var _hardResetting = false;
function _numericVersion(v) {
  var n = parseInt(String(v == null ? '' : v).replace(/[^0-9]/g, ''), 10);
  return isNaN(n) ? null : n;
}
async function hardResetClient() {
  if (_hardResetting) return;
  _hardResetting = true;
  // Flush whatever the invoice editor is holding BEFORE the reload. This reload
  // is one of the ways a half-typed invoice used to disappear without trace.
  try { await invDraftSave(true); } catch (e) {}
  try {
    if ('serviceWorker' in navigator) {
      var regs = await navigator.serviceWorker.getRegistrations();
      await Promise.all(regs.map(function (r) { return r.unregister(); }));
    }
  } catch (e) {}
  try {
    if (window.caches) {
      var keys = await caches.keys();
      await Promise.all(keys.map(function (k) { return caches.delete(k); }));
    }
  } catch (e) {}
  location.reload();
}

// The API says this build is too old to talk to it, but the tech is mid-invoice.
// showUpdateBar lives in index.html and is a quiet bar rather than an automatic
// reload, for exactly this reason: someone is always mid-form.
var _novaUpdateOffered = false;
function novaOfferForcedUpdate() {
  if (_novaUpdateOffered) return;
  _novaUpdateOffered = true;
  if (typeof showUpdateBar === 'function') {
    showUpdateBar(function () { invDraftSave(true); setTimeout(hardResetClient, 200); });
  } else {
    showToast('Nova needs to update. Save this invoice, then refresh the page.', 'info');
  }
}

async function api(method, path, body) {
  var isGet = String(method).toUpperCase() === 'GET';
  if (isGet && !_apiNoCache(path)) {
    var key = _apiCacheKey(path);
    var now = Date.now();
    var hit = _apiCache[key];
    if (hit && (now - hit.ts) < API_CACHE_TTL) {
      // Serve instantly; if it is a little stale, refresh quietly for next time.
      if ((now - hit.ts) > API_CACHE_SWR && !_apiInflight[key]) {
        var bgGen = _apiCacheGen;
        _apiInflight[key] = _apiFetch('GET', path, null, true).then(function (d) {
          if (bgGen === _apiCacheGen) _apiCache[key] = { data: d, ts: Date.now() };
          delete _apiInflight[key]; return d;
        }, function () { delete _apiInflight[key]; });
      }
      return _apiClone(hit.data);
    }
    if (_apiInflight[key]) return _apiClone(await _apiInflight[key]);
    var fgGen = _apiCacheGen;
    _apiInflight[key] = _apiFetch('GET', path).then(function (d) {
      if (fgGen === _apiCacheGen) _apiCache[key] = { data: d, ts: Date.now() };
      delete _apiInflight[key]; return d;
    }, function (e) { delete _apiInflight[key]; throw e; });
    return _apiClone(await _apiInflight[key]);
  }
  var result = await _apiFetch(method, path, body);
  if (!isGet) apiBustCache(); // any write invalidates cached reads so nothing goes stale
  return result;
}

async function _apiFetch(method, path, body, silent) {
  if (!silent) novaProgressStart();
  try {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (state.token) opts.headers['Authorization'] = 'Bearer ' + state.token;
  if (state.viewAsId) opts.headers['X-View-As'] = String(state.viewAsId);
  if (body) opts.body = JSON.stringify(body);
  let res;
  try {
    res = await fetch('/api' + path, opts);
  } catch(e) {
    throw new Error('Network error — could not reach the server. Check your connection.');
  }
  // Rolling JWT: pick up refreshed token from every response
  const newToken = res.headers.get('X-New-Token');
  if (newToken) {
    state.token = newToken;
    localStorage.setItem('po_token', newToken);
  }
  // Permission revision: if it moved, an admin changed our role / extra perms / the
  // role matrix. Refetch and re-render so it takes effect NOW, not on next reload.
  // Skipped while previewing as another user (View-As has its own identity).
  const permsRev = res.headers.get('X-Perms-Rev');
  if (permsRev && !state.viewAsId) {
    if (!state.permsRev) {
      state.permsRev = permsRev;
    } else if (permsRev !== state.permsRev) {
      state.permsRev = permsRev;
      refreshPermsAndRerender(); // fire-and-forget; must not block this request
    }
  }
  // Minimum client version: this build is too old to talk to the current API.
  // Flush caches and reload (the user stays signed in).
  const minVer = res.headers.get('X-Min-Version');
  if (minVer) {
    var _minN = _numericVersion(minVer);
    var _curN = _numericVersion(_resolvedAppVersion);
    // If we cannot tell what version we are, do nothing. Never reload on a guess.
    if (_minN !== null && _curN !== null && _curN < _minN) {
      // ...and never reload out from under a half-typed invoice. The draft is
      // flushed either way, but a page that vanishes while a customer is standing
      // there is its own kind of damage. Offer the reload instead of taking it.
      if (invEditorDirty()) { invDraftSave(true); novaOfferForcedUpdate(); }
      else hardResetClient();
    }
  }
  // Expired/invalid session: clear creds and bounce to login instead of getting stuck
  if (res.status === 401 && state.token) {
    try { invDraftSave(true); } catch (e) {}
    state.token = null;
    state.user = null;
    state.permsRev = null;
    state._permsLoaded = false;
    localStorage.removeItem('po_token');
    localStorage.removeItem('po_user');
    _apiCache = {};
    render();
    throw new Error('Your session expired \u2014 please sign in again.');
  }
  let data;
  try {
    data = await res.json();
  } catch(e) {
    throw new Error('Server error (status ' + res.status + '). Try again or check Railway logs.');
  }
  if (!res.ok) {
    // Carry the whole response body on the Error, not just the message. Some
    // endpoints reject with structured detail the caller needs to act on (the
    // invoice close-out gate returns cogs_missing[] so the form can put up a
    // fix-it modal instead of a dead-end alert).
    var _err = new Error(data.error || 'Request failed (status ' + res.status + ')');
    _err.status = res.status;
    _err.data = data;
    throw _err;
  }
  return data;
  } finally { if (!silent) novaProgressDone(); }
}

function themeIcon() {
  var light = document.documentElement.getAttribute('data-theme') === 'light';
  // Show the icon for the mode you'd switch TO: moon while light, sun while dark.
  return light
    ? '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 9 0 0 0 21 12.79z"/></svg>'
    : '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>';
}
function toggleTheme() {
  var nowLight = document.documentElement.getAttribute('data-theme') === 'light';
  var next = nowLight ? 'dark' : 'light';
  if (next === 'light') document.documentElement.setAttribute('data-theme', 'light');
  else document.documentElement.removeAttribute('data-theme');
  try { localStorage.setItem('po_theme', next); } catch (e) {}
  var btn = document.getElementById('theme-toggle-btn');
  if (btn) btn.innerHTML = themeIcon();
}
function isMobileNav() {
  try { return window.matchMedia('(max-width: 768px)').matches; } catch(e) { return false; }
}
function toggleSidebar() {
  var opening = !state.sidebarOpen;
  state.sidebarOpen = opening;
  // On mobile, open the drawer with every section collapsed so the user picks
  // what they want instead of landing on an auto-expanded sub-menu.
  if (opening && isMobileNav()) {
    state.sidebarSection = null;
    render();
  }
  var sb = document.getElementById('sidebar');
  var ov = document.getElementById('sidebar-overlay');
  if (sb) sb.classList.toggle('open', state.sidebarOpen);
  if (ov) ov.classList.toggle('open', state.sidebarOpen);
}

function closeSidebar() {
  state.sidebarOpen = false;
  var sb = document.getElementById('sidebar');
  var ov = document.getElementById('sidebar-overlay');
  if (sb) sb.classList.remove('open');
  if (ov) ov.classList.remove('open');
}

// getSidebarSection() now lives with the nav data model, further down this file.
function showToast(message, type) {
  var host = document.getElementById('nova-toast-host');
  if (!host) { host = document.createElement('div'); host.id = 'nova-toast-host'; document.body.appendChild(host); }
  var el = document.createElement('div');
  el.className = 'nova-toast nova-toast-' + (type === 'error' ? 'error' : type === 'success' ? 'success' : 'info');
  el.textContent = message;
  host.appendChild(el);
  requestAnimationFrame(function(){ el.classList.add('show'); });
  setTimeout(function(){ el.classList.remove('show'); setTimeout(function(){ if (el.parentNode) el.parentNode.removeChild(el); }, 260); }, type === 'error' ? 5000 : 3200);
}

function toggleSection(section, defaultView) {
  // A header tap expands/collapses the section in place and never navigates
  // (same on desktop and mobile); the user then taps a sub-item to change pages.
  // Refresh ONLY the sidebar nav so the main content is left untouched (no reload).
  //
  // Collapsing sets '' (NAV_COLLAPSED), not null. The two mean different things:
  // null = "nobody has chosen, derive the open section from the current view",
  // ''   = "the user explicitly closed it, leave everything shut".
  // With null, collapsing the section that owns the current view (e.g. closing
  // Customers while sitting on Google Reviews) snapped straight back open,
  // because buildNavHtml re-derived it from the view.
  state.sidebarSection = (state.sidebarSection === section) ? NAV_COLLAPSED : section;
  var nav = document.querySelector('.sidebar-nav');
  if (nav) { nav.innerHTML = buildNavHtml(); }
  else { render(); }
}
// Toggle a nested sub-section (one level below a group). Stops the click from
// also reaching the parent group header, and repaints only the sidebar so the
// main content is left untouched. Mirrors toggleSection's collapse sentinel.
function toggleSubSection(e, sub) {
  if (e && e.stopPropagation) e.stopPropagation();
  var cur = (state.sidebarSub == null) ? getSidebarSub(state.currentView) : state.sidebarSub;
  state.sidebarSub = (cur === sub) ? NAV_COLLAPSED : sub;
  var nav = document.querySelector('.sidebar-nav');
  if (nav) { nav.innerHTML = buildNavHtml(); }
  else { render(); }
}
function navigate(view, param) {
  closeSidebar();
  // A permission change landed while the user was mid-form, so we held the re-render
  // back. They have now navigated away on their own — the render() below applies it.
  if (state._permsRerenderPending) {
    state._permsRerenderPending = false;
    showToast('Your access was updated.', 'info');
  }
  state.currentView = view;
  state.currentParam = param || null;
  try { localStorage.setItem('po_view', view); if (param != null && param !== '') localStorage.setItem('po_param', String(param)); else localStorage.removeItem('po_param'); } catch(e) {}
  var sec = getSidebarSection(view);
  if (sec) state.sidebarSection = sec;
  var sub = getSidebarSub(view);
  if (sub) state.sidebarSub = sub;
  try {
    var _pk = (param != null ? String(param) : '');
    var _cur = history.state;
    if (!_cur || _cur.navView !== view || String(_cur.navParam == null ? '' : _cur.navParam) !== _pk) {
      history.pushState({ navView: view, navParam: (param != null ? param : null) }, '');
    }
  } catch (e) {}
  render();
}

// --- View As (admin role preview) -------------------------------------------
// UI-only preview: temporarily overrides state.user so all role-gated rendering
// (including can()) reflects the chosen role. Real admin kept in state.realUser.
// Nothing is persisted, so a page refresh exits the preview. Backend still
// authorizes the real admin, so this previews visibility/access only.
function enterViewAs(o) {
  var ru = state.realUser || state.user;
  if (!ru || ru.role !== 'admin') return;
  state.realUser = ru;
  state.user = { id: (o.id != null ? o.id : ru.id), name: (o.name || ru.name), email: ru.email, role: o.role };
  state.viewAsId = (o.id != null && o.id !== ru.id) ? o.id : null;
  state.viewAs = o.label;
  state.sidebarSection = null;
  navigate('home');
}
function viewAsRole(role) {
  enterViewAs({ role: role, label: roleLabel(role) + ' (preview)' });
}
function viewAsUser(id) {
  var u = (_usersData || []).filter(function(x) { return x.id === id; })[0];
  if (!u) return;
  enterViewAs({ id: u.id, name: u.name, role: u.role, label: u.name + ' \u2014 ' + u.role });
}
function exitViewAs() {
  if (state.realUser) { state.user = state.realUser; state.realUser = null; }
  state.viewAsId = null;
  state.viewAs = null;
  state.sidebarSection = null;
  navigate('home');
}
function onViewAsChange(role) {
  if (role === 'admin') exitViewAs(); else viewAsRole(role);
}

