var _geicoStats = null;
var _geicoRows = [];
var _geicoPage = 1;
var GEICO_PAGE_SIZE = 10;
var _geicoEmpRows = [];
var _geicoEmpPage = 1;
var GEICO_EMP_PAGE_SIZE = 10;
var _geicoEmployees = [];

async function renderGeicoReviews(el) {
  if (!can('manage_geico')) { el.innerHTML = '<div class="alert alert-error">Access denied.</div>'; return; }
  var cities = [];
  try { cities = await api('GET', '/cities'); } catch(e) { cities = []; }
  await geicoLoadEmployees();
  var cityOpts = '<option value="">All cities</option>' + cities.map(function(c){ return '<option value="' + escHtml(c.code) + '">' + escHtml(c.name) + '</option>'; }).join('');
  var iS = 'padding:8px 10px;background:var(--surface-color);border:1px solid rgba(249,115,22,0.35);border-radius:6px;color:var(--text-color);font-size:13px;outline:none';
  var lbl = 'display:block;font-size:11px;color:var(--text-muted-color);margin-bottom:4px';
  el.innerHTML =
    '<div class="page-header"><div><div class="page-title">Geico Surveys</div><div class="page-subtitle">ERS survey history by city, service &amp; rating</div></div></div>' +
    '<div id="geico-updated" style="font-size:12px;color:var(--text-muted-color);margin:-6px 0 14px">Auto-updates daily at 2:30 PM EST.</div>' +
    '<div id="geico-filters" style="display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin-bottom:16px">' +
      '<div><label style="' + lbl + '">From</label><input type="date" id="geico-from" style="' + iS + '" onchange="geicoLoad()" /></div>' +
      '<div><label style="' + lbl + '">To</label><input type="date" id="geico-to" style="' + iS + '" onchange="geicoLoad()" /></div>' +
      '<div><label style="' + lbl + '">City</label><select id="geico-city" style="' + iS + '" onchange="geicoLoad()">' + cityOpts + '</select></div>' +
      '<div><label style="' + lbl + '">Rating</label><select id="geico-rating" style="' + iS + '" onchange="geicoLoad()"><option value="">All ratings</option></select></div>' +
      '<div><label style="' + lbl + '">Service</label><select id="geico-service" style="' + iS + '" onchange="geicoLoad()"><option value="">All services</option></select></div>' +
      '<div><label style="' + lbl + '">State</label><select id="geico-state" style="' + iS + '" onchange="geicoLoad()"><option value="">All states</option></select></div>' +
      '<div><label style="' + lbl + '">Employee</label><select id="geico-employee" style="' + iS + '" onchange="geicoLoad()"><option value="">All employees</option></select></div>' +
      '<button class="btn btn-secondary btn-sm" onclick="geicoClearFilters()">Clear</button>' +
      '<button class="btn btn-secondary btn-sm" onclick="geicoExportCSV()">&#8595; Export CSV</button>' +
      '<button class="btn btn-secondary btn-sm" onclick="document.getElementById(\'geico-csv-input\').click()">&#8593; Import Employees</button>' +
      '<button class="btn btn-secondary btn-sm" onclick="geicoDownloadSample()">Import Sample CSV</button>' +
      '<input type="file" id="geico-csv-input" accept=".csv,text/csv" style="display:none" onchange="geicoOnCsvChosen(this)" />' +
    '</div>' +
    '<div id="geico-stats" style="margin-bottom:16px"></div>' +
    '<div id="geico-table-wrap"></div>' +
    '<div id="geico-employee-wrap" style="margin-top:16px"></div>';
  await geicoLoad(true);
}

function geicoClearFilters() {
  ['geico-from','geico-to','geico-city','geico-rating','geico-service','geico-state','geico-employee'].forEach(function(id){ var e=document.getElementById(id); if(e) e.value=''; });
  geicoLoad();
}

function geicoDateQS() {
  var qs = [];
  var from = (document.getElementById('geico-from')||{}).value;
  var to = (document.getElementById('geico-to')||{}).value;
  if (from) qs.push('from=' + encodeURIComponent(from));
  if (to) { var d = new Date(to + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate()+1); qs.push('to=' + encodeURIComponent(d.toISOString().slice(0,10))); }
  return qs;
}

function geicoListQS() {
  var qs = geicoDateQS();
  var city = (document.getElementById('geico-city')||{}).value;
  var rating = (document.getElementById('geico-rating')||{}).value;
  var service = (document.getElementById('geico-service')||{}).value;
  var st = (document.getElementById('geico-state')||{}).value;
  var emp = (document.getElementById('geico-employee')||{}).value;
  if (city) qs.push('city_code=' + encodeURIComponent(city));
  if (rating) qs.push('rating=' + encodeURIComponent(rating));
  if (service) qs.push('service=' + encodeURIComponent(service));
  if (st) qs.push('loss_state=' + encodeURIComponent(st));
  if (emp) qs.push('employee=' + encodeURIComponent(emp));
  return qs.length ? ('?' + qs.join('&')) : '';
}

async function geicoLoad(initial) {
  var statsEl = document.getElementById('geico-stats');
  var tableEl = document.getElementById('geico-table-wrap');
  if (statsEl) statsEl.innerHTML = '<div style="color:var(--text-muted-color);padding:12px">Loading...</div>';
  var dq = geicoDateQS();
  var dqs = dq.length ? ('?' + dq.join('&')) : '';
  try {
    var stats = await api('GET', '/geico/stats' + geicoListQS());
    var rows = await api('GET', '/geico' + geicoListQS());
    _geicoStats = stats; _geicoRows = rows; _geicoPage = 1;
    if (initial) geicoPopulateDropdowns(stats);
    geicoRenderStats(stats);
    geicoRenderTable(rows);
  } catch(e) {
    if (statsEl) statsEl.innerHTML = '<div class="alert alert-error">' + escHtml(e.message) + '</div>';
    if (tableEl) tableEl.innerHTML = '';
  }
}

function geicoPopulateDropdowns(stats) {
  function fill(id, arr) {
    var sel = document.getElementById(id); if (!sel) return;
    var cur = sel.value;
    var first = sel.options[0] ? sel.options[0].outerHTML : '';
    sel.innerHTML = first + (arr||[]).filter(function(x){ return x.k && x.k !== '(none)'; }).map(function(x){ return '<option value="' + escHtml(x.k) + '">' + escHtml(x.k) + '</option>'; }).join('');
    sel.value = cur;
  }
  fill('geico-rating', stats.byRating);
  fill('geico-service', stats.byService);
  fill('geico-state', stats.byState);
  var esel = document.getElementById('geico-employee');
  if (esel) {
    var ecur = esel.value;
    esel.innerHTML = '<option value="">All employees</option>' + (stats.byEmployee||[]).filter(function(x){ return x.k && x.k !== '(unassigned)'; }).map(function(x){ return '<option value="' + escHtml(x.k) + '">' + escHtml(x.k) + '</option>'; }).join('');
    esel.value = ecur;
  }
}

function geicoStatCard(label, value, sub, color) {
  return '<div class="card" style="flex:1;min-width:140px;padding:16px">' +
    '<div style="font-size:12px;color:var(--text-muted-color);text-transform:uppercase;letter-spacing:0.5px">' + escHtml(label) + '</div>' +
    '<div style="font-size:26px;font-weight:800;color:' + (color || 'var(--text-color)') + ';margin-top:4px">' + escHtml(String(value)) + '</div>' +
    (sub ? '<div style="font-size:12px;color:var(--text-muted-color);margin-top:2px">' + escHtml(sub) + '</div>' : '') +
    '</div>';
}

function geicoPctColor(p){ return p >= 90 ? '#4f9d69' : (p >= 80 ? '#c9a13b' : '#cf5a52'); }
function geicoRenderStats(s) {
  var el = document.getElementById('geico-stats'); if (!el) return;
  var total = s.total || 0;
  var exc = (s.byRating||[]).filter(function(r){ return /excellent/i.test(r.k); }).reduce(function(a,b){ return a + b.n; }, 0);
  var rated = (s.byRating||[]).filter(function(r){ return r.k !== '(none)'; }).reduce(function(a,b){ return a + b.n; }, 0);
  var excPct = rated ? Math.round(exc*100/rated) : 0;
  var otPct = s.onTimeAnswered ? Math.round(s.onTime*100/s.onTimeAnswered) : 0;
  var nCities = (s.byCity||[]).filter(function(c){ return c.k !== '(unmatched)'; }).length;
  var unmatched = (s.byCity||[]).filter(function(c){ return c.k === '(unmatched)'; }).reduce(function(a,b){ return a + b.n; }, 0);
  var cards =
    geicoStatCard('Total Surveys', total, '') +
    geicoStatCard('% Excellent Surveys', excPct + '%', exc + ' of ' + rated, geicoPctColor(excPct)) +
    geicoStatCard('On-Time', otPct + '%', (s.onTime||0) + ' of ' + (s.onTimeAnswered||0) + ' answered', geicoPctColor(otPct)) +
    geicoStatCard('Cities', nCities, unmatched ? (unmatched + ' unmatched') : '');
  // Per-city scorecards (mirrors the Google Reviews "By Location" cards): survey
  // count, a big color-coded % Excellent headline, on-time % beneath, city name.
  // Unmatched surveys are surfaced in the Cities stat card above, not here.
  var cityRows = (s.byCity||[]).filter(function(c){ return c.k !== '(unmatched)'; }).map(function(c){
    var cRated = c.rated || 0, cExc = c.excellent || 0, cAns = c.answered || 0, cOn = c.on_time || 0;
    return {
      name: c.k, n: c.n || 0,
      excPct: cRated ? Math.round(cExc*100/cRated) : 0,
      otPct: cAns ? Math.round(cOn*100/cAns) : 0,
      rated: cRated, exc: cExc, answered: cAns, hasRating: cRated > 0
    };
  });
  cityRows.sort(function(a,b){
    if (a.hasRating !== b.hasRating) return a.hasRating ? -1 : 1;
    return (b.excPct - a.excPct) || (b.n - a.n) || String(a.name).localeCompare(String(b.name));
  });
  var cityCards = cityRows.length ? cityRows.map(function(c){
    var big = c.hasRating ? (c.excPct + '<span style="font-size:18px">%</span>') : '<span style="font-size:20px">n/a</span>';
    var bigColor = c.hasRating ? geicoPctColor(c.excPct) : 'var(--text-muted-color)';
    var sub = c.hasRating
      ? ('Excellent' + (c.answered ? ' &middot; ' + c.otPct + '% on-time' : ''))
      : (c.answered ? (c.otPct + '% on-time') : 'No ratings yet');
    var tip = c.name + ' — ' + c.exc + ' of ' + c.rated + ' Excellent' + (c.answered ? (', ' + c.otPct + '% on-time') : '');
    return '<div class="card" style="padding:16px;min-width:150px;flex:0 0 auto;text-align:center" title="' + escHtml(tip) + '">' +
        '<div style="font-size:13px;color:var(--text-muted-color)">' + c.n.toLocaleString() + ' survey' + (c.n===1?'':'s') + '</div>' +
        '<div style="font-size:32px;font-weight:800;color:' + bigColor + ';line-height:1.1;margin:2px 0 4px">' + big + '</div>' +
        '<div style="font-size:11px;color:var(--text-muted-color);margin-bottom:8px">' + sub + '</div>' +
        '<div style="font-size:13px;color:var(--text-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:180px">' + escHtml(c.name) + '</div>' +
      '</div>';
  }).join('') : '<div style="color:var(--text-muted-color);font-size:13px">No city data for this range.</div>';
  var breakdown =
    '<div class="card" style="flex:1;min-width:260px;padding:16px">' +
      '<div style="font-size:12px;color:var(--text-muted-color);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:12px">By City</div>' +
      '<div style="display:flex;flex-wrap:wrap;gap:12px">' + cityCards + '</div>' +
    '</div>';
  el.innerHTML = '<div style="display:flex;flex-wrap:wrap;gap:12px;margin-bottom:12px">' + cards + '</div>' +
    '<div style="display:flex;flex-wrap:wrap;gap:12px">' + breakdown + '</div>';
  _geicoEmpPage = 1;
  geicoRenderEmployeeTable(s);
}

function geicoEmployeeScored(s) {
  var all = (s.byEmployee||[]).filter(function(e){ return e.k !== '(unassigned)'; });
  var totExc = 0, totRated = 0;
  all.forEach(function(e){ totExc += (e.excellent||0); totRated += (e.rated||0); });
  var globalExc = totRated ? (totExc/totRated) : 0.85;
  var C = 5; // prior strength (in surveys) — pulls small samples toward the team average
  all.forEach(function(e){
    var rated = e.rated||0, exc = e.excellent||0;
    e._excPct = rated ? Math.round(exc*100/rated) : 0;
    e._otPct = e.answered ? Math.round((e.on_time||0)*100/e.answered) : 0;
    e._score = (exc + C*globalExc) / (rated + C); // survey-weighted (Bayesian) excellent rate
  });
  all.sort(function(a,b){ return (b._score - a._score) || ((b.n||0)-(a.n||0)) || String(a.k).localeCompare(String(b.k)); });
  return all;
}

function geicoEmpPaginate(p) { _geicoEmpPage = p; geicoRenderEmployeeTable(_geicoStats); }
function geicoEmpPageSize(v) { GEICO_EMP_PAGE_SIZE = parsePageSize(v); _geicoEmpPage = 1; geicoRenderEmployeeTable(_geicoStats); }

function geicoRenderEmployeeTable(s) {
  var el = document.getElementById('geico-employee-wrap'); if (!el || !s) return;
  var emps = geicoEmployeeScored(s);
  _geicoEmpRows = emps;
  var unassigned = (s.byEmployee||[]).filter(function(e){ return e.k === '(unassigned)'; }).reduce(function(a,b){ return a + b.n; }, 0);
  var head = '<div style="font-size:12px;color:var(--text-muted-color);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">By Employee' + (unassigned ? ' &middot; ' + unassigned + ' unassigned' : '') + '</div>';
  if (!emps.length) {
    el.innerHTML = '<div class="card" style="padding:16px">' + head + '<div style="color:var(--text-muted-color);font-size:13px">No employees assigned yet. Pick one from the Employee dropdown on any survey, or export the surveys, fill in the Employee column and use Import Employees.</div></div>';
    return;
  }
  var total = emps.length;
  var totalPages = Math.max(1, Math.ceil(total / GEICO_EMP_PAGE_SIZE));
  if (_geicoEmpPage > totalPages) _geicoEmpPage = totalPages;
  if (_geicoEmpPage < 1) _geicoEmpPage = 1;
  var start = (_geicoEmpPage - 1) * GEICO_EMP_PAGE_SIZE;
  var page = emps.slice(start, start + GEICO_EMP_PAGE_SIZE);
  var body = page.map(function(e, i){
    var rank = start + i + 1;
    var score = Math.round(e._score*100);
    return '<tr>' +
      '<td style="text-align:right;color:var(--text-muted-color);width:28px">' + rank + '</td>' +
      '<td>' + escHtml(e.k) + '</td>' +
      '<td style="text-align:right">' + e.n + '</td>' +
      '<td style="text-align:right;color:' + geicoPctColor(e._excPct) + '">' + e._excPct + '% <span style="color:var(--text-muted-color)">(' + e.excellent + '/' + e.rated + ')</span></td>' +
      '<td style="text-align:right;font-weight:700;color:' + geicoPctColor(score) + '">' + score + '</td>' +
    '</tr>';
  }).join('');
  var sizeCtl = pageSizeControl(GEICO_EMP_PAGE_SIZE, 'geicoEmpPageSize');
  var btns = '';
  if (totalPages > 1) {
    for (var i2 = 1; i2 <= totalPages; i2++) { btns += '<button class="btn btn-sm ' + (i2 === _geicoEmpPage ? 'btn-primary' : 'btn-secondary') + '" onclick="geicoEmpPaginate(' + i2 + ')">' + i2 + '</button> '; }
    btns = '<button class="btn btn-secondary btn-sm" onclick="geicoEmpPaginate(' + (_geicoEmpPage-1) + ')" ' + (_geicoEmpPage===1?'disabled':'') + '>&lsaquo;</button> ' + btns + '<button class="btn btn-secondary btn-sm" onclick="geicoEmpPaginate(' + (_geicoEmpPage+1) + ')" ' + (_geicoEmpPage===totalPages?'disabled':'') + '>&rsaquo;</button>';
  }
  var showing = (start+1) + '-' + Math.min(start+GEICO_EMP_PAGE_SIZE, total);
  el.innerHTML = '<div class="card" style="padding:16px">' + head +
    '<div style="font-size:12px;color:var(--text-muted-color);margin-bottom:8px">Ranked by survey-weighted score<span class="nova-info" onclick="this.classList.toggle(\'open\');event.stopPropagation()"><i class="ni-ico">i</i><span class="ni-pop"><strong>How the Score works</strong>It is a survey-weighted Excellent rate. Each person starts with 5 baseline surveys at the team average, then their real surveys are added on top. Someone with only 1-2 surveys stays near the team average instead of topping the list on a tiny sample; as more surveys come in, the Score moves to their true Excellent %. This keeps proven, high-volume performers ranked fairly against small samples.</span></span> &middot; showing ' + showing + ' of ' + total + '</div>' +
    '<div class="table-wrap"><table><thead><tr><th style="text-align:right">#</th><th>Employee</th><th style="text-align:right">Surveys</th><th style="text-align:right">% Excellent</th><th style="text-align:right" title="Survey-weighted Excellent rate: small samples are pulled toward the team average so high-volume performers rank fairly">Score</th></tr></thead><tbody>' + body + '</tbody></table></div>' +
    '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px">' + sizeCtl + ' ' + btns + '</div></div>';
}

function geicoRatingBadge(r) {
  if (!r) return '—';
  var c = /excellent/i.test(r) ? '#22c55e' : /good/i.test(r) ? '#84cc16' : /fair/i.test(r) ? '#f59e0b' : /poor|bad/i.test(r) ? '#ef4444' : '#9ca3af';
  return '<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:12px;font-weight:600;color:#fff;background:' + c + '">' + escHtml(r) + '</span>';
}

// Same buckets jobs/geicoComplaints.js uses server-side. Kept in step with it so
// the File button appears on exactly the surveys that could be complaints.
function geicoRatingBucket(r) {
  var s = (r == null ? '' : String(r)).trim();
  if (!s) return null;
  if (/poor|bad/i.test(s)) return 'poor';
  if (/fair/i.test(s)) return 'fair';
  if (/excellent/i.test(s)) return 'excellent';
  if (/good/i.test(s)) return 'good';
  return 'unknown';
}

// Open a Customer Feedback complaint for one survey by hand. Poor and Fair
// surveys file themselves on a schedule; this covers older ones and any
// better-rated survey a manager still wants worked.
async function geicoFileComplaint(poNumber, btn) {
  if (btn) { btn.disabled = true; btn.textContent = 'Filing...'; }
  try {
    var r = await api('POST', '/geico/file-complaint', { po_number: poNumber });
    for (var i = 0; i < _geicoRows.length; i++) {
      if (String(_geicoRows[i].po_number) === String(poNumber)) {
        _geicoRows[i].complaint_id = r.id;
        if (!_geicoRows[i].complaint_status) _geicoRows[i].complaint_status = 'new';
        break;
      }
    }
    geicoRenderTable(_geicoRows);
    showToast(r.duplicate ? ('That survey is already complaint #' + r.id + '.') : ('Complaint #' + r.id + ' filed and assigned.'), r.duplicate ? 'info' : 'success');
  } catch (e) {
    if (btn) { btn.disabled = false; btn.textContent = 'File'; }
    showToast(e.message || 'Could not file the complaint.', 'error');
  }
}

// The roster behind the Employee dropdown. Real Nova users only, active first -
// a survey has to credit a real person for the By Employee leaderboard to mean
// anything.
async function geicoLoadEmployees() {
  try { _geicoEmployees = await api('GET', '/geico/employees') || []; }
  catch (e) { _geicoEmployees = []; }
}

function geicoEmployeeOptions(r) {
  var sel = r.employee_user_id ? String(r.employee_user_id) : '';
  var act = '', former = '';
  for (var i = 0; i < _geicoEmployees.length; i++) {
    var u = _geicoEmployees[i];
    var opt = '<option value="' + u.id + '"' + (sel === String(u.id) ? ' selected' : '') + '>' + escHtml(u.name || '') + '</option>';
    if (u.active) act += opt; else former += opt;
  }
  // A name the CSV import could not match to anybody stays visible under a
  // sentinel value, selected, so the cell still reads as the raw Geico Tech ID
  // and importing never loses information it could not map.
  var raw = (!sel && r.employee_name)
    ? '<option value="__raw__" selected>' + escHtml(r.employee_name) + ' (imported)</option>'
    : '';
  return raw + '<option value=""' + ((!sel && !raw) ? ' selected' : '') + '>Unassigned</option>' +
    act + (former ? '<optgroup label="Former">' + former + '</optgroup>' : '');
}

function geicoEmployeeCell(r) {
  if (!r.po_number) return '<span style="color:var(--text-muted-color)">' + escHtml(r.employee_name || '\u2014') + '</span>';
  var st = 'padding:4px 6px;background:var(--surface-color);border:1px solid rgba(249,115,22,0.28);border-radius:6px;color:var(--text-color);font-size:12px;max-width:180px';
  var title = r.employee_source === 'manual' ? 'Picked by hand' : (r.employee_source === 'import' ? 'From the employee CSV import' : 'Nobody credited yet');
  return '<select style="' + st + '" title="' + escHtml(title) + '" onchange="geicoAssignEmployee(&#39;' + escHtml(String(r.po_number)) + '&#39;, this.value, this)">' + geicoEmployeeOptions(r) + '</select>';
}

// Credit one survey to a person. A pick made here is stamped 'manual' server
// side and a later CSV import will not overwrite it.
async function geicoAssignEmployee(poNumber, value, selEl) {
  if (value === '__raw__') return;
  var userId = value ? parseInt(value, 10) : null;
  if (selEl) selEl.disabled = true;
  try {
    var r = await api('PUT', '/geico/assign-employee', { po_number: poNumber, user_id: userId });
    for (var i = 0; i < _geicoRows.length; i++) {
      if (String(_geicoRows[i].po_number) === String(poNumber)) {
        _geicoRows[i].employee_name = r.employee_name || null;
        _geicoRows[i].employee_user_id = r.employee_user_id || null;
        _geicoRows[i].employee_source = r.employee_source || null;
        break;
      }
    }
    geicoRenderTable(_geicoRows);
    showToast(r.employee_name ? ('Credited to ' + r.employee_name + '.') : 'Employee cleared.', 'success');
    geicoRefreshStats();
  } catch (e) {
    if (selEl) { selEl.disabled = false; selEl.style.borderColor = '#dc2626'; }
    showToast((e && e.message) ? e.message : 'Could not save that employee.', 'error');
  }
}

// Repaint the stat cards and the By Employee leaderboard after one assignment.
// Deliberately NOT geicoLoad(), which resets the table to page 1 and would
// bounce someone out of the page they are working through.
async function geicoRefreshStats() {
  try {
    var stats = await api('GET', '/geico/stats' + geicoListQS());
    _geicoStats = stats;
    geicoRenderStats(stats);
    // Only rebuild the Employee filter list when nothing is filtered by it: the
    // row just reassigned may have been the last one under the selected name,
    // and dropping that option would silently clear the filter.
    var esel = document.getElementById('geico-employee');
    if (esel && !esel.value) geicoPopulateDropdowns(stats);
  } catch (e) { /* the table already shows the truth; a stale stat card is not worth an error banner */ }
}

function geicoPaginate(p) { _geicoPage = p; geicoRenderTable(_geicoRows); }
function geicoPageSize(v) { GEICO_PAGE_SIZE = parsePageSize(v); _geicoPage = 1; geicoRenderTable(_geicoRows); }
function geicoRenderTable(rows) {
  var wrap = document.getElementById('geico-table-wrap'); if (!wrap) return;
  var canFileComplaint = can('manage_feedback');
  var canOpenComplaint = can('view_feedback');
  var total = rows.length;
  var totalPages = Math.max(1, Math.ceil(total / GEICO_PAGE_SIZE));
  if (_geicoPage > totalPages) _geicoPage = totalPages;
  if (_geicoPage < 1) _geicoPage = 1;
  var _start = (_geicoPage - 1) * GEICO_PAGE_SIZE;
  var page = rows.slice(_start, _start + GEICO_PAGE_SIZE);
  var _showing = total === 0 ? '0' : ((_start + 1) + '-' + Math.min(_start + GEICO_PAGE_SIZE, total));
  var _sizeCtl = pageSizeControl(GEICO_PAGE_SIZE, 'geicoPageSize');
  var _btns = '';
  if (totalPages > 1) {
    for (var _i = 1; _i <= totalPages; _i++) { _btns += '<button class="btn btn-sm ' + (_i === _geicoPage ? 'btn-primary' : 'btn-secondary') + '" onclick="geicoPaginate(' + _i + ')">' + _i + '</button> '; }
    _btns = '<button class="btn btn-secondary btn-sm" onclick="geicoPaginate(' + (_geicoPage-1) + ')" ' + (_geicoPage===1?'disabled':'') + '>&lsaquo;</button> ' + _btns + '<button class="btn btn-secondary btn-sm" onclick="geicoPaginate(' + (_geicoPage+1) + ')" ' + (_geicoPage===totalPages?'disabled':'') + '>&rsaquo;</button>';
  }
  var _pager = '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px">' + _sizeCtl + _btns + '</div>';
  wrap.innerHTML =
    '<div style="font-size:12px;color:var(--text-muted-color);margin-bottom:8px">Showing ' + _showing + ' of ' + total + ' survey' + (total===1?'':'s') + '</div>' +
    '<div class="card"><div class="table-wrap"><table>' +
      '<thead><tr><th>Received</th><th>Account #</th><th>City</th><th>PO #</th><th>Service</th><th>State</th><th>Dispatch</th><th>On Time</th><th>Arrival</th><th>Rating</th><th>Employee</th><th style="text-align:center">Complaint</th></tr></thead><tbody>' +
      (total === 0
        ? '<tr><td colspan="12" style="text-align:center;color:var(--text-muted-color);padding:32px">No surveys found.</td></tr>'
        : page.map(function(r){
            var cmpCell;
            if (r.complaint_id) {
              var statusLine = r.complaint_status ? '<div style="font-size:10px;color:var(--text-muted-color)">' + escHtml(FB_STATUS[r.complaint_status] || r.complaint_status) + '</div>' : '';
              // The complaint number opens the record so the survey list doubles as
              // a progress view. Only a link for someone who can actually open it -
              // renderFeedbackDetail refuses without view_feedback, so without the
              // gate this would be a dead click for a Geico-only manager.
              cmpCell = (canOpenComplaint
                ? '<a href="#" onclick="feedbackOpen(' + r.complaint_id + ');return false" title="Open complaint #' + r.complaint_id + ' to track progress" style="color:var(--primary);font-weight:600;text-decoration:none">#' + r.complaint_id + '</a>'
                : '<span title="A complaint is on file. Ask an admin for access to Customer Feedback to open it." style="font-weight:600">#' + r.complaint_id + '</span>'
              ) + statusLine;
            } else if (canFileComplaint && r.po_number && geicoRatingBucket(r.rating) !== 'excellent') {
              cmpCell = '<button class="btn btn-secondary btn-sm" title="Open a complaint for this survey" onclick="geicoFileComplaint(&#39;' + escHtml(String(r.po_number)) + '&#39;, this)">File</button>';
            } else {
              cmpCell = '<span style="color:var(--text-muted-color)">—</span>';
            }
            return '<tr>' +
              '<td style="white-space:nowrap">' + escHtml(r.date_received||'—') + '</td>' +
              '<td>' + escHtml(r.account_number||'—') + '</td>' +
              '<td>' + escHtml(r.city_name||'—') + '</td>' +
              '<td>' + escHtml(r.po_number||'—') + '</td>' +
              '<td>' + escHtml(r.service||'—') + '</td>' +
              '<td>' + escHtml(r.loss_state||'—') + '</td>' +
              '<td style="white-space:nowrap">' + escHtml(r.date_of_dispatch||'—') + '</td>' +
              '<td>' + escHtml(r.arrived_on_time||'—') + '</td>' +
              '<td>' + escHtml(r.time_to_arrive||'—') + '</td>' +
              '<td>' + geicoRatingBadge(r.rating) + '</td>' +
              '<td>' + geicoEmployeeCell(r) + '</td>' +
              '<td style="white-space:nowrap;text-align:center">' + cmpCell + '</td>' +
            '</tr>';
          }).join('')) +
      '</tbody></table></div></div>' + _pager;
}

function geicoExportCSV() {
  var rows = _geicoRows || [];
  if (!rows.length) { novaAlert('Nothing to export with the current filters.'); return; }
  var header = ['Received','Account #','City','PO #','Service','State','Dispatch','On Time','Arrival','Rating','Employee'];
  var lines = [header.map(csvCell).join(',')];
  rows.forEach(function(r){
    lines.push([
      r.date_received||'', r.account_number||'', r.city_name||'', r.po_number||'', r.service||'',
      r.loss_state||'', r.date_of_dispatch||'', r.arrived_on_time||'', r.time_to_arrive||'', r.rating||'', r.employee_name||''
    ].map(csvCell).join(','));
  });
  var blob = new Blob([lines.join('\r\n')], { type: 'text/csv' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'geico-surveys-' + new Date().toISOString().slice(0,10) + '.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(a.href);
}

function geicoDownloadSample() {
  var csv = 'Account PO,Tech ID\r\n' +
    'G587926170,"Benson, Chris"\r\n' +
    'G143226170,"Jacques, Daniel"\r\n' +
    'G328826170,"Sims, Jason"\r\n';
  var blob = new Blob([csv], { type: 'text/csv' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'geico-import-sample.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(a.href);
}

function geicoOnCsvChosen(input) {
  var file = input.files && input.files[0];
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function(e){ input.value = ''; geicoHandleCsv(e.target.result); };
  reader.readAsText(file);
}

async function geicoHandleCsv(text) {
  var grid = parsePartsCSV(text);
  if (grid.length < 2) { novaAlert('That CSV looks empty. Export the surveys first, fill in the Employee column, then import.'); return; }
  var header = grid[0].map(function(h){ return (h||'').trim().toLowerCase().replace(/[\s#]+/g,'_').replace(/_+$/,''); });
  function colIdx(names){ for (var n=0;n<names.length;n++){ var k=header.indexOf(names[n]); if (k!==-1) return k; } return -1; }
  var poi = colIdx(['account_po','po','po_number','po_no','ponumber']);
  var ei = colIdx(['tech_id','employee','employee_name','name','tech','technician']);
  if (poi === -1) { novaAlert('Could not find an "Account PO" (or "PO #") column in that CSV. Use the Import Sample CSV as your template.'); return; }
  if (ei === -1) { novaAlert('Could not find a "Tech ID" (or "Employee") column in that CSV. Use the Import Sample CSV as your template.'); return; }
  var rows = [];
  for (var i=1;i<grid.length;i++){
    var po=(grid[i][poi]||'').trim();
    var emp=(grid[i][ei]||'').trim();
    if (po && emp) rows.push({ po_number: po, employee_name: emp });
  }
  if (!rows.length) { novaAlert('No rows had both a PO # and an Employee name. Fill in the Employee column and try again.'); return; }
  if (!await novaConfirm('Assign employee names to ' + rows.length + ' survey' + (rows.length===1?'':'s') + '?')) return;
  try {
    var resp = await api('POST', '/geico/import-employees', { rows: rows });
    var msg = 'Updated ' + resp.updated + ' survey' + (resp.updated===1?'':'s') + '.';
    if (resp.matched != null) msg += '\nMatched ' + resp.matched + ' to a Nova user.';
    if (resp.unmatched) msg += '\n' + resp.unmatched + ' name(s) matched nobody on the roster and were kept as plain text.';
    if (resp.unmatchedNames && resp.unmatchedNames.length) msg += '\nUnmatched: ' + resp.unmatchedNames.join(', ') + '.';
    if (resp.manualKept) msg += '\nLeft ' + resp.manualKept + ' row(s) alone because an employee was picked by hand there.';
    if (resp.skipped) msg += '\nSkipped ' + resp.skipped + ' row(s) with a missing PO # or name.';
    if (resp.notFound) { msg += '\n' + resp.notFound + ' PO #(s) were not found'; if (resp.notFoundList && resp.notFoundList.length) msg += ': ' + resp.notFoundList.join(', '); msg += '.'; }
    novaAlert(msg);
    geicoLoad(true);
  } catch(e) {
    novaAlert('Import failed: ' + (e && e.message ? e.message : e));
  }
}
